  assert.equal(total(items, 0.1), 855);
});

test('zero discount keeps the bulk-only total (#12)', () => {
  const items = Array.from({ length: 10 }, () => ({ price: 100, qty: 1 }));
  assert.equal(total(items, 0), 950);
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
});
```

